import React from 'react';
import { Button, Tooltip, ButtonProps } from 'antd';
import { LockOutlined } from '@ant-design/icons';
import { usePermissions } from '../hooks/usePermissions';

interface PermissionButtonProps extends ButtonProps {
  permission?: string;
  role?: string;
  requireAll?: boolean; // Требовать все указанные права/роли
  fallbackText?: string;
  showTooltip?: boolean;
  children: React.ReactNode;
}

const PermissionButton: React.FC<PermissionButtonProps> = ({
  permission,
  role,
  requireAll = false,
  fallbackText = "Недостаточно прав",
  showTooltip = true,
  children,
  disabled,
  ...buttonProps
}) => {
  const { hasPermission, hasRole } = usePermissions();

  // Проверка доступа
  const checkAccess = (): boolean => {
    const conditions: boolean[] = [];
    
    if (permission) {
      conditions.push(hasPermission(permission));
    }
    
    if (role) {
      conditions.push(hasRole(role));
    }
    
    if (conditions.length === 0) {
      return true; // Если не указаны условия, доступ разрешен
    }
    
    return requireAll ? conditions.every(Boolean) : conditions.some(Boolean);
  };

  const hasAccess = checkAccess();
  const isDisabled = disabled || !hasAccess;

  // Определяем текст для tooltip
  const getTooltipText = (): string => {
    if (disabled && hasAccess) {
      return "Кнопка отключена";
    }
    if (!hasAccess) {
      const missingItems: string[] = [];
      if (permission && !hasPermission(permission)) {
        missingItems.push(`право "${permission}"`);
      }
      if (role && !hasRole(role)) {
        missingItems.push(`роль "${role}"`);
      }
      return `Требуется: ${missingItems.join(', ')}`;
    }
    return "";
  };

  const tooltipText = getTooltipText();

  const button = (
    <Button
      {...buttonProps}
      disabled={isDisabled}
      icon={!hasAccess ? <LockOutlined /> : buttonProps.icon}
    >
      {!hasAccess ? fallbackText : children}
    </Button>
  );

  // Показываем tooltip только если есть текст и включена опция
  if (showTooltip && tooltipText) {
    return (
      <Tooltip title={tooltipText} placement="top">
        {button}
      </Tooltip>
    );
  }

  return button;
};

export default PermissionButton;
